#!/usr/bin/env Rscript

# Copy shared files from the repo root to every module whose .qmd references
# them, under their autogenerated name:
#   web_and_slides.lua -> web_and_slides_autogenerated.lua
#
# Register this as `pre-render` in _quarto.yml to run it before every local render.
#
# Usage: Rscript sync_filter.r        (run from the repo root)

files <- c(
  "web_and_slides.lua" = "web_and_slides_autogenerated.lua"   # also referenced by web_and_slides.r
)

qmds <- list.files(pattern = "[.]qmd$", recursive = TRUE)

for (source_file in names(files)) {
  copy_name <- files[[source_file]]

  if (!file.exists(source_file)) {
    stop("Cannot find ", source_file, " in ", getwd(),
         " -- run this from the repo root")
  }

  banner <- c(
    paste0(copy_name, " -- AUTOGENERATED, DO NOT EDIT."),
    paste0("Copied from the repo root's ", source_file, " by sync_filter.r (see _quarto.yml)."),
    "Edit that file instead; this copy exists so the module is self-contained."
  )
  banner <- if (grepl("[.]lua$", copy_name)) c(paste("--", banner), "--") else c("<!--", banner, "-->")
  content <- c(banner, readLines(source_file, warn = FALSE))

  # every directory holding a .qmd that references this copy
  uses    <- vapply(qmds, function(f) any(grepl(copy_name, readLines(f, warn = FALSE), fixed = TRUE)),
                    logical(1))
  targets <- setdiff(unique(dirname(qmds[uses])), ".")
  if (length(targets) == 0) message("sync_filter: no .qmd references ", copy_name)

  for (m in targets) {
    dest <- file.path(m, copy_name)
    if (file.exists(dest) && identical(readLines(dest, warn = FALSE), content)) next
    writeLines(content, dest)
    message("sync_filter: wrote ", dest)
  }
}
